      if (workerUp && r.json.worker !== 'up') return undefined;
      return r.json;
    });
  } catch {
    throw new CheckFailure(`timed out after ${timeoutMs} ms waiting for ${want}; last response: ${clip(last, 300)}`);
  }
}

