/** Request validation for `POST /api/jobs`. */

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = ['input', 'steps', 'failAttempts'];

export function isJsonContentType(header: string | undefined): boolean {
  if (header === undefined) return false;
  return (header.split(';')[0] ?? '').trim().toLowerCase() === 'application/json';
}

export type BodyValidation = { value: NewJob } | { fields: FieldError[] };

/** Validates an already-parsed JSON body, applying defaults. Collects every problem it finds. */
export function validateBody(raw: unknown): BodyValidation {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    return { fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  }
  const obj = raw as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.includes(key)) fields.push({ field: key, message: 'unknown field' });
  }

  const input = obj.input;
  if (input === undefined) {
    fields.push({ field: 'input', message: 'input is required' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be only whitespace' });
  }

  const steps = integerField(obj, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(obj, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0 || typeof input !== 'string') return { fields };
  return { value: { input, steps, failAttempts } };
}

function integerField(obj: Record<string, unknown>, name: string, min: number, max: number, def: number, fields: FieldError[]): number {
  const v = obj[name];
  if (v === undefined) return def;
  const range = `${name} must be an integer from ${min} to ${max}`;
  if (typeof v !== 'number' || !Number.isInteger(v)) {
    fields.push({ field: name, message: range });
    return def;
  }
  if (v < min || v > max) {
    fields.push({ field: name, message: range });
    return def;
  }
  return v;
}

