import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { openDatabase } from './db.ts';
import { toJob, type Job, type JobRow } from './jobs.ts';
import { IDEMPOTENCY_KEY_PATTERN, isJsonContentType, validateBody, type FieldError, type NewJob } from './validate.ts';

const MAX_BODY_BYTES = 64 * 1024;
/** The worker counts as up if its heartbeat is at most this old. */
const HEARTBEAT_FRESH_MS = 3_000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const stmt = {
  jobById: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  jobByKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
  insertJob: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, run_after, idempotency_key, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?, ?)`,
  ),
  listJobs: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  workerHeartbeat: db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'"),
};

function jobRow(id: string): JobRow | undefined {
  return stmt.jobById.get(id) as unknown as JobRow | undefined;
}

type SubmitOutcome = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/**
 * Creates a job, or replays the job stored under the idempotency key. The lookup and insert run in
 * one immediate transaction so no two submissions with the same key can both create a job.
 */
function submit(value: NewJob, key: string | null): SubmitOutcome {
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== null) {
      const existing = stmt.jobByKey.get(key) as unknown as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        const same =
          existing.input === value.input && existing.steps === value.steps && existing.fail_attempts === value.failAttempts;
        return same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    stmt.insertJob.run(id, value.input, value.steps, value.failAttempts, key, now, now);
    const row = jobRow(id);
    db.exec('COMMIT');
    if (!row) throw new Error('inserted job not found');
    return { kind: 'created', job: toJob(row) };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function handleHealth(res: ServerResponse): void {
  const row = stmt.workerHeartbeat.get() as unknown as { at: number } | undefined;
  const up = row !== undefined && Date.now() - row.at <= HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  }

  let key: string | null = null;
  const keyHeader = req.headers['idempotency-key'];
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY_PATTERN.test(keyHeader)) key = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const text = await readBody(req);
  let value: NewJob | undefined;
  if (text === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    let parseOk = true;
    try {
      parsed = JSON.parse(text);
    } catch {
      parseOk = false;
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
    if (parseOk) {
      const result = validateBody(parsed);
      if ('fields' in result) fields.push(...result.fields);
      else value = result.value;
    }
  }

  if (fields.length > 0 || value === undefined) {
    return sendError(res, 400, 'invalid_request', 'The submission is invalid.', fields);
  }

  const outcome = submit(value, key);
  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

function handleGetJob(res: ServerResponse, rawId: string): void {
  let id: string;
  try {
    id = decodeURIComponent(rawId);
  } catch {
    return sendError(res, 404, 'not_found', 'No job with that id.');
  }
  const row = jobRow(id);
  if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, toJob(row));
}

function handleListJobs(res: ServerResponse): void {
  const rows = stmt.listJobs.all() as unknown as JobRow[];
  send(res, 200, { jobs: rows.map(toJob) });
}

function methodNotAllowed(res: ServerResponse): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.');
}

function notFound(res: ServerResponse): void {
  sendError(res, 404, 'not_found', 'Not found.');
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  // HEAD is answered like GET (without a body, as Node does for HEAD responses).
  const method = req.method === 'HEAD' ? 'GET' : req.method;
  const path = (req.url ?? '/').split('?')[0] ?? '/';

  if (path === '/health') return method === 'GET' ? handleHealth(res) : methodNotAllowed(res);

  if (path === '/') {
    if (method !== 'GET') return methodNotAllowed(res);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(uiHtml);
    return;
  }

  if (path === '/api/jobs') {
    if (method === 'GET') return handleListJobs(res);
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) return method === 'GET' ? handleGetJob(res, match[1] ?? '') : methodNotAllowed(res);

  return notFound(res);
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (res.headersSent) res.end();
    else sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

const port = process.env.PORT ? Number(process.env.PORT) : 3000;
server.listen(port, () => console.log(`server listening on ${port}`));

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 1_000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

