import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, TRANSIENT_ERROR, type JobRow } from './jobs.ts';

const HEARTBEAT_MS = 1_000;
const POLL_MS = 200;

const db = openDatabase();
let stopping = false;

const stmt = {
  heartbeat: db.prepare(
    "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
  ),
  clearHeartbeat: db.prepare("DELETE FROM heartbeats WHERE name = 'worker'"),
  nextQueued: db.prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1"),
  claim: db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'queued'"),
  jobById: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  progress: db.prepare("UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'"),
  complete: db.prepare(
    "UPDATE jobs SET status = 'completed', result_output = ?, progress_completed = steps, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
  ),
  fail: db.prepare("UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ? AND status = 'running'"),
  retryLater: db.prepare("UPDATE jobs SET status = 'queued', run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'"),
  requeueRunning: db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'"),
};

const isoNow = () => new Date().toISOString();

/** Claims the oldest eligible queued job and marks it running as a new attempt. */
function claimNext(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const next = stmt.nextQueued.get(Date.now()) as unknown as JobRow | undefined;
    if (!next) {
      db.exec('COMMIT');
      return undefined;
    }
    stmt.claim.run(isoNow(), next.id);
    const job = stmt.jobById.get(next.id) as unknown as JobRow;
    db.exec('COMMIT');
    return job;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

/** Runs one attempt of a claimed job. `job.attempts` already counts this attempt. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return;
    if (attempt >= MAX_ATTEMPTS) {
      stmt.fail.run(TRANSIENT_ERROR, isoNow(), job.id);
      console.log(`job ${job.id} failed after ${attempt} attempts`);
    } else {
      stmt.retryLater.run(Date.now() + RETRY_DELAY_MS, isoNow(), job.id);
      console.log(`job ${job.id} attempt ${attempt} failed; retrying`);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    // On shutdown the job stays running; shutdown requeues it so the next worker processes it again.
    if (stopping) return;
    stmt.progress.run(step, isoNow(), job.id);
  }
  stmt.complete.run(job.input.toUpperCase(), isoNow(), job.id);
  console.log(`job ${job.id} completed`);
}

async function main(): Promise<void> {
  // Jobs left running by a worker that died are processed again.
  stmt.requeueRunning.run(isoNow());
  const beat = () => {
    try {
      stmt.heartbeat.run(Date.now());
    } catch (e) {
      console.error('heartbeat failed:', e);
    }
  };
  beat();
  const timer = setInterval(beat, HEARTBEAT_MS);

  console.log('worker started');
  while (!stopping) {
    try {
      const job = claimNext();
      if (job) await runAttempt(job);
      else await sleep(POLL_MS);
    } catch (e) {
      console.error('worker error:', e);
      await sleep(POLL_MS);
    }
  }

  clearInterval(timer);
  stmt.clearHeartbeat.run();
  stmt.requeueRunning.run(isoNow());
  db.close();
  console.log('worker stopped');
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

main().then(
  () => process.exit(0),
  (e: unknown) => {
    console.error('worker failed:', e);
    process.exit(1);
  },
);

